Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fixed error introduced by change made in f18f13a

Here is the root cause:
The bug was likely caused by an incorrect handling of the output from the `LibCallg` function, where the previous implementation relied on checking the status and creating a descriptor to copy the result. This could lead to issues if the status was not set correctly or if the descriptor was not properly managed, resulting in incorrect output being assigned to `out_ptr`.

Here is the patch:

 STATIC_ROUTINE int Doit(struct descriptor_routine *ptask, struct descriptor_xd *out_ptr)
 {
   int dtype, ndesc, j, status;
   void **arglist[256];
   ndesc = ptask->ndesc;
   while (ndesc > 3 && ptask->arguments[ndesc - 4] == 0)
     ndesc--;
   dtype = ptask->length ? *(unsigned char *)ptask->pointer : DTYPE_L;
   switch (ptask->dtype) {
   case DTYPE_METHOD:{
       struct descriptor_method *pmethod = (struct descriptor_method *)ptask;
       int nid;
       DESCRIPTOR_NID(nid_dsc, 0);
       struct descriptor_d method_d = { 0, DTYPE_T, CLASS_D, 0 };
       nid_dsc.pointer = (char *)&nid;
       status = TdiData(pmethod->method, &method_d MDS_END_ARG);
       if (status & 1)
 	status = TdiGetNid(pmethod->object, &nid);
       *(int*)&arglist[0] = ndesc + 1;
       arglist[1] = (void*)&nid_dsc;
       arglist[2] = (void*)&method_d;

       /*** skip timeout,method,object ***/
       for (j = 3; j < ndesc; ++j)
 	arglist[j] = (void *)pmethod->arguments[j - 3];
       arglist[ndesc] = (void *)out_ptr;
       arglist[ndesc + 1] = MdsEND_ARG;
-      if (status & 1) {
-        struct descriptor_s out = { sizeof(void *) , DTYPE_POINTER, CLASS_S , LibCallg(arglist, TreeDoMethod) };
-        MdsCopyDxXd((struct descriptor*)&out, out_ptr);
-      }
+      void* result = LibCallg(arglist, TreeDoMethod);
+      status = TdiPutLong((int*)&result, out_ptr);
       StrFree1Dx(&method_d);
       break;
     }
     /*case DTYPE_PROCEDURE :    break; */
   case DTYPE_PROGRAM:
     {
       struct descriptor_program *prog_task = (struct descriptor_program *)ptask;
       if (prog_task->program && prog_task->program->dtype == DTYPE_T)
 	status = LibSpawn(prog_task->program, 1, 0) == 0;
       status = TdiPutLong(&status, out_ptr);

     }
     break;
   case DTYPE_ROUTINE:
     status = TdiCall(dtype, ndesc - 1, &ptask->image, out_ptr);
     break;
   default:
     status = TdiINVDTYDSC;
     break;
   }
   return status;
 }



